// rushing into the frame: rising noise and a sweeping tone, cut at the cut
const n = kit.noise('white'), hp = ctx.createBiquadFilter(); hp.type = 'bandpass'; hp.Q.value = 1.2;
kit.env(hp.frequency, [[0, 400], [0.53, 9000]], 'exp');
const g = ctx.createGain(); kit.env(g.gain, [[0, 0.001], [0.5, 1], [0.545, 0.001]], 'exp');
n.connect(hp).connect(g).connect(ctx.destination); n.start(0);
const o = ctx.createOscillator(); o.type = 'sawtooth'; kit.env(o.frequency, [[0, 160], [0.53, 1800]], 'exp');
const f = ctx.createBiquadFilter(); f.type = 'lowpass'; f.frequency.value = 3000;
const go = ctx.createGain(); kit.env(go.gain, [[0, 0.001], [0.5, 0.25], [0.545, 0.0001]], 'exp');
o.connect(f).connect(go).connect(ctx.destination); o.start(0); o.stop(0.55);
